def max_tandem_repeat(s, k):
    n = len(s)
    max_len = 0

    # Check for tandem repeats in the original string
    for i in range(n):
        if 2 * (n - i) <= k:
            break
        found = True
        for j in range(1, n - i):
            if s[i:i+j] != s[i+j:i+2*j]:
                found = False
                break
        if found:
            max_len = 2 * (n - i)

    # Check for tandem repeats after adding k characters
    for i in range(k + 1):
        for j in range(i):
            if i - j >= n:
                break
            test_s = s + 'a' * i + s[:j]
            for l in range(min(j, n), 0, -1):
                if test_s[-l:] == test_s[-2*l:-l]:
                    max_len = 2 * l
                    break
            else:
                continue
            break

    return max_len

